ol li {
  list-style-type: none;
}

.modal {
  display: flex;
  justify-content: center;
  align-items: center;
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.5);
}

.modal-content {
  background: white;
  padding: 20px;
  border-radius: 5px;
  width: 500px;
  text-align: center;
  display: flex;
  flex-direction: column;
  position: relative;
}

.modal-content h2 {
  margin: 10px 0 25px 0;
  color: black;
}

.close {
  position: absolute;
  top: 15px;
  right: 15px;
  font-size: 20px;
  cursor: pointer;
}

form div {
  margin-bottom: 20px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  margin-left: 75px;
}

form div label {
  font-size: 12px;
  margin-bottom: 5px;
  text-align: center;
}

form div input {
  width: 80%;
  padding: 10px;
  box-sizing: border-box;
}

input {
  width: 100%;
  padding: 8px;
  box-sizing: border-box;
}

