  font-size: 16px;
  margin: 20px 5px;
}

.btn-change-modal:hover {
  background-color: #0056b3;
}


.password-checks {
  margin-top: 5px;
  display: flex;
  flex-direction: column;
  text-align: left;
}

.password-checks p {
  font-size: 10px;
  margin: 3px 0;
}

.password-checks p.green {
  color: green;
}

.password-checks p.red {
  color: red;
}



.password-check-indicators {
